import LiquidGlass
import Observation
import SwiftUI
#if os(iOS)
import UIKit
#elseif os(macOS)
import AppKit
#endif

/// The shared wallpapers (generated by assets/wallpapers/generate.swift).
enum Wallpaper: String, CaseIterable, Identifiable {
    case aurora, dunes, ocean, midnight

    var id: String { rawValue }
    var title: String { rawValue.capitalized }

    /// The wallpaper filling the space it is offered.
    var view: some View {
        Image(rawValue)
            .resizable()
            .scaledToFill()
            .frame(minWidth: 0, maxWidth: .infinity, minHeight: 0, maxHeight: .infinity)
            .clipped()
            .accessibilityHidden(true)
    }
}

/// The Materials lab's live options.
@Observable
final class LabSettings {
    var material = GlassMaterial.clear
    var appearance = GlassAppearance.automatic
    var refraction = 60.0
    var radius = 48.0
    var capsule = false
    var tint: LabTint = .none
    var wallpaper = Wallpaper.dunes

    var glassRadius: GlassRadius { capsule ? .capsule : .points(radius) }
}

/// Tints the lab offers, from the system palette.
enum LabTint: String, CaseIterable, Identifiable {
    case none, blue, purple, pink, orange, green

    var id: String { rawValue }

    var color: Color? {
        switch self {
        case .none: nil
        case .blue: Color(red: 0, green: 0.478, blue: 1)
        case .purple: Color(red: 0.686, green: 0.322, blue: 0.871)
        case .pink: Color(red: 1, green: 0.176, blue: 0.333)
        case .orange: Color(red: 1, green: 0.584, blue: 0)
        case .green: Color(red: 0.204, green: 0.780, blue: 0.349)
        }
    }
}

/// A section heading drawn straight on a wallpaper.
struct SectionHeader: View {
    let title: String

    var body: some View {
        Text(title)
            .font(.footnote.weight(.semibold))
            .textCase(.uppercase)
            .kerning(0.6)
            .foregroundStyle(.white.opacity(0.9))
            .shadow(color: .black.opacity(0.25), radius: 4, y: 1)
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding(.horizontal, 4)
            .accessibilityAddTraits(.isHeader)
    }
}

/// Room for the floating tab bar at the bottom of every page.
enum StudioLayout {
    #if os(macOS)
    static let tabBarClearance: CGFloat = 72
    static let pagePadding: CGFloat = 32
    #else
    static let tabBarClearance: CGFloat = 84
    static let pagePadding: CGFloat = 20
    #endif
}

/// Lays its children out in rows, wrapping when a row is full, so the demo's
/// button rows survive the largest text sizes.
struct FlowLayout: Layout {
    var spacing: CGFloat = 10

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let rows = rows(for: subviews, width: proposal.width ?? .infinity)
        let width = rows.map { $0.width }.max() ?? 0
        let height = rows.map(\.height).reduce(0, +) + spacing * CGFloat(max(0, rows.count - 1))
        return CGSize(width: width, height: height)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        var y = bounds.minY
        for row in rows(for: subviews, width: bounds.width) {
            var x = bounds.minX
            for index in row.indices {
                let size = Self.size(of: subviews[index], width: bounds.width)
                subviews[index].place(at: CGPoint(x: x, y: y + (row.height - size.height) / 2), proposal: ProposedViewSize(size))
                x += size.width + spacing
            }
            y += row.height + spacing
        }
    }

    /// A child's size, never wider than the row: a child wider than the
    /// row (a long label at the largest text sizes) gets the row's width
    /// and truncates or wraps instead of overflowing.
    private static func size(of subview: LayoutSubview, width: CGFloat) -> CGSize {
        let ideal = subview.sizeThatFits(.unspecified)
        guard width.isFinite, ideal.width > width else { return ideal }
        return subview.sizeThatFits(ProposedViewSize(width: width, height: nil))
    }

    private struct Row {
        var indices: [Int] = []
        var width: CGFloat = 0
        var height: CGFloat = 0
    }

    private func rows(for subviews: Subviews, width: CGFloat) -> [Row] {
        var rows: [Row] = []
        var row = Row()
        for index in subviews.indices {
            let size = Self.size(of: subviews[index], width: width)
            let needed = row.indices.isEmpty ? size.width : row.width + spacing + size.width
            if needed > width, !row.indices.isEmpty {
                rows.append(row)
                row = Row()
            }
            row.width = row.indices.isEmpty ? size.width : row.width + spacing + size.width
            row.height = max(row.height, size.height)
            row.indices.append(index)
        }
        if !row.indices.isEmpty { rows.append(row) }
        return rows
    }
}

/// Shares the project's website through the system: the share sheet on
/// iOS, the sharing picker on macOS, anchored to the button that asked.
@MainActor
enum StudioShare {
    static let url = URL(string: "https://liquid-glass-engineering.vercel.app")!

    /// Presents the share UI next to `anchor`, a frame in the global space.
    static func present(from anchor: CGRect) {
        #if os(iOS)
        let scenes = UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }
        guard let scene = scenes.first(where: { $0.activationState == .foregroundActive }) ?? scenes.first,
              let window = scene.keyWindow ?? scene.windows.first,
              var presenter = window.rootViewController else { return }
        while let presented = presenter.presentedViewController { presenter = presented }
        let sheet = UIActivityViewController(activityItems: [url], applicationActivities: nil)
        // On iPad the sheet is a popover pointing at the button.
        sheet.popoverPresentationController?.sourceView = window
        sheet.popoverPresentationController?.sourceRect = anchor
        presenter.present(sheet, animated: true)
        #elseif os(macOS)
        guard let view = NSApp.keyWindow?.contentView else { return }
        // SwiftUI's global space starts at the top left of the window's content.
        let rect = NSRect(
            x: anchor.minX, y: view.isFlipped ? anchor.minY : view.bounds.height - anchor.maxY,
            width: anchor.width, height: anchor.height
        )
        NSSharingServicePicker(items: [url]).show(relativeTo: rect, of: view, preferredEdge: .minY)
        #endif
    }
}

/// A toolbar button that shares the project's website.
struct ShareButton: View {
    @State private var anchor = CGRect.zero

    var body: some View {
        GlassButton(icon: "square.and.arrow.up", label: "Share") { StudioShare.present(from: anchor) }
            .background {
                GeometryReader { proxy in
                    Color.clear.onChange(of: proxy.frame(in: .global), initial: true) { _, frame in anchor = frame }
                }
            }
    }
}

/// The top edge of a page whose content scrolls under the status bar (iOS)
/// or the window's buttons (macOS): scrolled content fades out as it
/// passes under the bar, and the wallpaper beneath the bar blurs
/// progressively under a haze of the color scheme's background, so the
/// clock and the window buttons stay legible over any wallpaper in either
/// appearance.
struct ScrollEdge: ViewModifier {
    /// How far above the page's top edge the content fades out.
    var fade: CGFloat = 20

    @Environment(\.colorScheme) private var colorScheme

    func body(content: Content) -> some View {
        content
            .mask(alignment: .top) {
                VStack(spacing: 0) {
                    LinearGradient(colors: [.clear, .black], startPoint: .top, endPoint: .bottom)
                        .frame(height: fade)
                    Color.black
                }
                .padding(.top, -fade)
            }
            .overlay {
                // Under the bar only: the reader ignores the top safe area
                // and still reports how tall it is.
                GeometryReader { proxy in
                    let height = proxy.safeAreaInsets.top
                    ZStack(alignment: .top) {
                        GlassProgressiveBlur(edge: .top, size: height)
                        LinearGradient(colors: [haze.opacity(0.5), haze.opacity(0)], startPoint: .top, endPoint: .bottom)
                            .frame(height: height)
                    }
                }
                .ignoresSafeArea(edges: .top)
                .allowsHitTesting(false)
                .accessibilityHidden(true)
            }
    }

    private var haze: Color { colorScheme == .dark ? .black : .white }
}
